import{_ as t,o as a,c as n,ag as o}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"FunctionEndpoint — takoform_function_endpoint","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/function/function-endpoint.md","filePath":"proposals/function/function-endpoint.md"}'),i={name:"proposals/function/function-endpoint.md"};function r(s,e,d,c,h,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="functionendpoint-—-takoform-function-endpoint" tabindex="-1">FunctionEndpoint — <code>takoform_function_endpoint</code> <a class="header-anchor" href="#functionendpoint-—-takoform-function-endpoint" aria-label="Permalink to &quot;FunctionEndpoint — `takoform_function_endpoint`&quot;">​</a></h1><blockquote><p>Historical/deferred candidate (English-only). This non-Edge Form is not in the current official Edge16 corpus or Current navigation.</p></blockquote><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A team wants their function callable over plain HTTPS, now, without owning a gateway or a domain. External clients send requests to an address the host assigns and publishes; TLS termination and the naming scheme are the host&#39;s obligation, never portable state.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>attachment</code>. Inward activation is an attachment resource, never a binding (decision 0010). Deleting the attachment removes the address and never deletes the function.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>function</code> is the only desired member, and it is immutable: changing it replaces the attachment. A request at the assigned address is delivered as one <code>http</code> invocation event of the <code>function.runtime@1.0.0</code> contract to a version the function&#39;s ACTIVE DEPLOYMENT selects, and the handler&#39;s return value is mapped to the HTTP response exactly as that contract fixes. Promotion and rollback move what answers without the endpoint being re-applied and without the address changing; each request is served entirely by one version.</p><p>The address is published as outputs: <code>hostname</code> is the assigned DNS name, and <code>url</code> is exactly <code>https://</code> + that hostname + <code>/</code>. A portable author may rely on a value being returned, on the scheme being HTTPS, and on the address routing to the active deployment — and on nothing about its shape: they must not parse it, assert a suffix, or reconstruct it from the resource name (<a href="./../../spec/decisions/0024-a-worker-is-reachable-at-a-host-assigned-address.html">decision 0024</a>, <a href="./../../spec/decisions/0025-declared-outputs-are-a-typed-contract.html">decision 0025</a>).</p><p>A function has at most one endpoint. A host that cannot assign an address refuses the attachment with <code>unsupported_capability</code> rather than answering with an address it did not assign.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Reachability without a name of one&#39;s own is one complete observable fact: the function answers at an address, over HTTPS, at the path root. Merging it with an author-owned hostname would need a selector token between two different requests, exactly as the Edge family records for its endpoint pair.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>An author-owned hostname is a future custom-domain attachment of this family. Access control — callers restricted by identity or signature — is policy, a separate authority-bearing Form. Scheduled or source-driven invocation is not HTTP activation at all and lives in the source&#39;s family.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>The assigned address must be stable for the life of one incarnation: a consumer holding the URL must not find it moved by a deployment change it did not make. A second endpoint against one function must be refused deterministically, by the function&#39;s UID rather than its name. Attaching while the function has no deployment must be refused, per the family aggregate. Deleting the function while the endpoint exists must fail with <code>dependency_in_use</code>. Import must recover the function reference and the assigned address exactly, without minting a new one.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The direct HTTPS URL of a proven cloud function service, with the address published as a typed output contract and its authorization modes left to separate policy work.</p>',22)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
